static const COLORREF pink=RGB(245,222,240), canvas=RGB(248,231,245), ink=RGB(62,48,61), muted=RGB(142,124,141), line=RGB(236,220,233), white=RGB(255,253,255), rose=RGB(221,155,202);
static int imax(int a,int b){return a>b?a:b;}
static void fill(HDC d,RECT r,COLORREF c){HBRUSH b=CreateSolidBrush(c);FillRect(d,&r,b);DeleteObject(b);}
static void frame(HDC d,RECT r,COLORREF c){HPEN p=CreatePen(PS_SOLID,1,c);HGDIOBJ old=SelectObject(d,p);HGDIOBJ brush=SelectObject(d,GetStockObject(NULL_BRUSH));Rectangle(d,r.left,r.top,r.right,r.bottom);SelectObject(d,brush);SelectObject(d,old);DeleteObject(p);}
static void text(HDC d,int x,int y,const wchar_t *s,COLORREF c,int size,bool bold){SetBkMode(d,TRANSPARENT);SetTextColor(d,c);HFONT f=CreateFontW(-size,0,0,0,bold?FW_SEMIBOLD:FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,CLEARTYPE_QUALITY,DEFAULT_PITCH,L"Segoe UI");HGDIOBJ o=SelectObject(d,f);TextOutW(d,x,y,s,(int)wcslen(s));SelectObject(d,o);DeleteObject(f);}
void ui_layout(DangoApp *a,int w,int h){a->window_width=w;a->window_height=h;int pad=16,top=62,bottom=36;int avail=w-2*pad;int rail=(int)(avail*a->panel_left_ratio);int insp=(int)(avail*a->inspector_ratio);int gap=12;int timeline_h=(int)((h-top-bottom)*a->timeline_ratio);a->toolrail=(RECT){pad,top,pad+rail,h-timeline_h-bottom};a->preview=(RECT){a->toolrail.right+gap,top,w-pad-insp-gap,h-timeline_h-bottom};a->inspector=(RECT){a->preview.right+gap,top,w-pad,h-timeline_h-bottom};a->timeline=(RECT){pad,h-timeline_h-bottom,w-pad,h-bottom};a->splitter_left=a->toolrail.right+gap/2;a->splitter_center=a->preview.right+gap/2;a->splitter_bottom=a->timeline.top+bottom/2;}
static void rounded(HDC d,RECT r,COLORREF color){HBRUSH b=CreateSolidBrush(color);HPEN p=CreatePen(PS_SOLID,1,RGB(255,255,255));HGDIOBJ ob=SelectObject(d,b),op=SelectObject(d,p);RoundRect(d,r.left,r.top,r.right,r.bottom,12,12);SelectObject(d,ob);SelectObject(d,op);DeleteObject(b);DeleteObject(p);}
static void draw_clip(DangoApp *a,HDC d,RECT lane,Clip *c,double zoom){double x=lane.left+(c->start-a->project.scroll_seconds)*zoom;double w=c->duration*zoom;RECT r={(LONG)x,lane.top+7,(LONG)(x+w),lane.bottom-7};if(r.right<lane.left||r.left>lane.right)return;COLORREF color=c->kind==LANE_AUDIO?RGB(229,240,229):c->kind==LANE_EFFECT?RGB(244,222,238):RGB(219,235,222);fill(d,r,color);frame(d,r,c->selected?RGB(194,105,171):RGB(192,218,198));if(c->kind==LANE_EFFECT){RECT ov={r.left+3,r.top+3,r.right-3,r.top+15};fill(d,ov,RGB(239,196,224));}wchar_t name[192];MultiByteToWideChar(CP_UTF8,0,c->name,-1,name,192);RECT tr={r.left+6,r.top+15,r.right-18,r.bottom-2};SetBkMode(d,TRANSPARENT);SetTextColor(d,ink);DrawTextW(d,name,-1,&tr,DT_LEFT|DT_VCENTER|DT_SINGLELINE|DT_END_ELLIPSIS);for(unsigned k=0;k<c->keyframe_count;k++){int kx=r.left+(int)(c->keyframes[k].time*zoom);POINT diamond[4]={{kx,r.top+4},{kx+4,r.top+8},{kx,r.top+12},{kx-4,r.top+8}};HBRUSH b=CreateSolidBrush(RGB(191,104,166));HGDIOBJ old=SelectObject(d,b);Polygon(d,diamond,4);SelectObject(d,old);DeleteObject(b);}}
static RECT timeline_lane(DangoApp *a,int row,int rows){int header=108,ruler=31,rowh=(a->timeline.bottom-a->timeline.top-ruler-38)/imax(rows,1);return (RECT){a->timeline.left+header,a->timeline.top+ruler+row*rowh,a->timeline.right,a->timeline.top+ruler+(row+1)*rowh};}
void ui_paint(DangoApp *a,HDC d){RECT all={0,0,a->window_width,a->window_height};fill(d,all,canvas);text(d,18,18,L"●  Dango",ink,19,true);text(d,133,23,L"Untitled project   ●",muted,12,false);
  rounded(d,a->toolrail,white);const wchar_t *tools[]={L"◉  Select  V",L"✂  Blade   C",L"✋ Hand    H",L"T  Text"};for(int i=0;i<4;i++){RECT r={a->toolrail.left+6,a->toolrail.top+10+i*43,a->toolrail.right-6,a->toolrail.top+48+i*43};if((int)a->project.tool==i)fill(d,r,pink);text(d,r.left+6,r.top+11,tools[i],ink,11,i==a->project.tool);}
  rounded(d,a->preview,white);text(d,a->preview.left+14,a->preview.top+12,L"VIEWER",muted,10,true);RECT stage={a->preview.left+12,a->preview.top+37,a->preview.right-12,a->preview.bottom-46};fill(d,stage,RGB(222,234,235));RECT hills={stage.left,stage.top+(stage.bottom-stage.top)*2/3,stage.right,stage.bottom};fill(d,hills,RGB(164,187,161));text(d,stage.left+40,stage.top+34,L"Your next little film.",white,30,true);text(d,stage.left+18,stage.bottom-27,L"▶",ink,18,true);text(d,a->preview.left+14,a->preview.bottom-31,L"00:00:04:12    /    00:00:18:00",ink,11,true);text(d,a->preview.right-125,a->preview.bottom-31,L"Preview  0.5×",muted,11,false);
  rounded(d,a->inspector,white);text(d,a->inspector.left+14,a->inspector.top+14,L"Kontrol",a->tab==TAB_KONTROL?ink:muted,13,true);text(d,a->inspector.left+76,a->inspector.top+14,L"Effectz",a->tab==TAB_EFFECTZ?ink:muted,13,true);text(d,a->inspector.left+139,a->inspector.top+14,L"Media",a->tab==TAB_MEDIA?ink:muted,13,true);frame(d,(RECT){a->inspector.left+12,a->inspector.top+37,a->inspector.right-12,a->inspector.top+38},line);
  if(a->tab==TAB_MEDIA){text(d,a->inspector.left+15,a->inspector.top+54,L"Import media",ink,13,true);text(d,a->inspector.left+15,a->inspector.top+84,L"Click + or press Ctrl+I",muted,11,false);}else if(a->tab==TAB_EFFECTZ){text(d,a->inspector.left+15,a->inspector.top+54,L"Click to apply to selected video",muted,10,false);text(d,a->inspector.left+15,a->inspector.top+88,L"✦  Soft glow",ink,12,true);text(d,a->inspector.left+15,a->inspector.top+123,L"◉  Swirl",ink,12,true);text(d,a->inspector.left+15,a->inspector.top+158,L"☼  Warm film",ink,12,true);}else{const wchar_t *props[]={L"Position X / Y",L"Size",L"Rotation",L"Speed",L"Opacity"};double values[]={a->project.controls.position_x,a->project.controls.size,a->project.controls.rotation,a->project.controls.speed,a->project.controls.opacity};wchar_t val[64];for(int i=0;i<PROP_COUNT;i++){int y=a->inspector.top+54+i*47;text(d,a->inspector.left+15,y,props[i],muted,11,false);if(i==0)swprintf_s(val,64,L"%.0f, %.0f",a->project.controls.position_x,a->project.controls.position_y);else swprintf_s(val,64,L"%.0f%s",values[i],(i==1||i==3||i==4)?L"%":L"°");text(d,a->inspector.right-75,y,val,ink,10,true);RECT bar={a->inspector.left+15,y+25,a->inspector.right-70,y+28};fill(d,bar,line);RECT active=bar;active.right=active.left+(active.right-active.left)/2;fill(d,active,rose);text(d,a->inspector.right-53,y+17,L"Reset",RGB(181,100,159),9,false);}
    text(d,a->inspector.left+15,a->inspector.top+300,L"KEYFRAMES",muted,9,true);text(d,a->inspector.left+15,a->inspector.top+320,L"◇ Add keyframe at playhead",ink,10,false);}
  rounded(d,a->timeline,white);text(d,a->timeline.left+14,a->timeline.top+10,L"TIMELINE     Main sequence",ink,12,true);text(d,a->timeline.right-126,a->timeline.top+10,L"−   ━━━●━━   +",muted,11,false);int top=a->timeline.top+31;RECT ruler={a->timeline.left,top,a->timeline.right,top+24};fill(d,ruler,RGB(255,250,253));for(int t=0;t<7;t++){wchar_t tick[16];swprintf_s(tick,16,L"%02d:%02d",t/2,(t%2)*5);int x=a->timeline.left+108+(int)(t*5*a->project.pixels_per_second);text(d,x,top+5,tick,muted,9,false);}
  int total=a->project.visible_video_tracks+a->project.visible_audio_tracks;int rowh=(a->timeline.bottom-top-38)/imax(total,1);for(int row=0;row<total;row++){int y=top+24+row*rowh;RECT head={a->timeline.left,y,a->timeline.left+108,y+rowh};RECT lane={a->timeline.left+108,y,a->timeline.right,y+rowh};fill(d,head,RGB(255,250,253));frame(d,(RECT){lane.left,lane.top,lane.right,lane.bottom},line);wchar_t track[8];if(row<a->project.visible_video_tracks)swprintf_s(track,8,L"V%d",row+1);else swprintf_s(track,8,L"A%d",row-a->project.visible_video_tracks+1);text(d,head.left+14,y+7,track,muted,10,true);
    for(size_t j=0;j<a->project.clip_count;j++){Clip *c=&a->project.clips[j];int display=c->kind==LANE_AUDIO?a->project.visible_video_tracks+c->track:c->track;if(c->kind==LANE_EFFECT)continue;if(display==row)draw_clip(a,d,lane,c,a->project.pixels_per_second);}
    for(size_t j=0;j<a->project.clip_count;j++){Clip *e=&a->project.clips[j];if(e->kind==LANE_EFFECT&&e->track==(row<a->project.visible_video_tracks?row:-1))draw_clip(a,d,lane,e,a->project.pixels_per_second);}}
  int playx=a->timeline.left+108+(int)((a->project.playhead-a->project.scroll_seconds)*a->project.pixels_per_second);HPEN ph=CreatePen(PS_SOLID,1,RGB(200,111,174));HGDIOBJ old=SelectObject(d,ph);MoveToEx(d,playx,top,NULL);LineTo(d,playx,a->timeline.bottom-20);SelectObject(d,old);DeleteObject(ph);text(d,a->timeline.left+14,a->timeline.bottom-17,a->status[0]?a->status:L"Magnetic timeline  ●",muted,9,false);
  RECT split={a->splitter_left-4,62,a->splitter_left+4,a->timeline.top};fill(d,split,RGB(248,231,245));split=(RECT){a->splitter_center-4,62,a->splitter_center+4,a->timeline.top};fill(d,split,RGB(248,231,245));split=(RECT){16,a->splitter_bottom-4,a->window_width-16,a->splitter_bottom+4};fill(d,split,RGB(248,231,245));}
static bool inside(RECT r,int x,int y){return x>=r.left&&x<r.right&&y>=r.top&&y<r.bottom;}
void ui_mouse_down(DangoApp *a,int x,int y,UINT flags){(void)flags;if(abs(x-a->splitter_left)<7&&y<a->timeline.top){a->drag_splitter=0;return;}if(abs(x-a->splitter_center)<7&&y<a->timeline.top){a->drag_splitter=1;return;}if(abs(y-a->splitter_bottom)<7){a->drag_splitter=2;return;}
  if(inside(a->toolrail,x,y)){int i=(y-a->toolrail.top-10)/43;if(i>=0&&i<4){a->project.tool=(Tool)i;InvalidateRect(a->hwnd,NULL,FALSE);}return;}
  if(inside(a->inspector,x,y)){if(y<a->inspector.top+42){int rel=x-a->inspector.left;a->tab=rel<70?TAB_KONTROL:rel<132?TAB_EFFECTZ:TAB_MEDIA;}else if(a->tab==TAB_MEDIA&&y<a->inspector.top+82){media_import_dialog(a);}else if(a->tab==TAB_EFFECTZ&&y>=a->inspector.top+78&&y<a->inspector.top+190){Clip*c=project_find_clip(&a->project,a->project.selected_id);if(!c||c->kind!=LANE_VIDEO){wcsncpy_s(a->status,256,L"Select a video clip first to apply an effect.",_TRUNCATE);}else{int effect=(y-(a->inspector.top+78))/35;const char* names[]={"Soft glow","Swirl","Warm film"};project_add_effect(&a->project,c->id,names[effect>2?2:effect]);wcsncpy_s(a->status,256,L"Effect added as an overlay on the selected clip.",_TRUNCATE);}}else if(a->tab==TAB_KONTROL){int i=(y-(a->inspector.top+54))/47;if(i>=0&&i<PROP_COUNT&&x>a->inspector.right-62)project_reset_control(&a->project,(Property)i);else if(y>=a->inspector.top+314&&a->project.selected_id){double value=i==1?a->project.controls.size:i==2?a->project.controls.rotation:i==3?a->project.controls.speed:i==4?a->project.controls.opacity:100;project_add_keyframe(&a->project,a->project.selected_id,a->project.playhead,value);}}InvalidateRect(a->hwnd,NULL,FALSE);return;}
  if(inside(a->timeline,x,y)){int total=a->project.visible_video_tracks+a->project.visible_audio_tracks;int top=a->timeline.top+55;int rh=(a->timeline.bottom-top-38)/imax(total,1);int row=(y-top)/imax(rh,1);if(y<a->timeline.top+30){a->project.playhead=fmax(0,(x-a->timeline.left-108)/a->project.pixels_per_second);InvalidateRect(a->hwnd,NULL,FALSE);return;}if(row>=0&&row<total){RECT lane=timeline_lane(a,row,total);for(size_t i=0;i<a->project.clip_count;i++){Clip*c=&a->project.clips[i];int display=c->kind==LANE_AUDIO?a->project.visible_video_tracks+c->track:c->track;int l=lane.left+(int)((c->start-a->project.scroll_seconds)*a->project.pixels_per_second),r=l+(int)(c->duration*a->project.pixels_per_second);if(display==row&&c->kind!=LANE_EFFECT&&x>=l&&x<=r){project_select_clip(&a->project,c->id);a->drag_clip=(int)i;a->drag_origin.x=x;a->drag_start=c->start;a->dragging_clip=true;SetCapture(a->hwnd);break;}}if(!a->dragging_clip){a->project.playhead=fmax(0,(x-lane.left)/a->project.pixels_per_second+a->project.scroll_seconds);}}InvalidateRect(a->hwnd,NULL,FALSE);}}
void ui_mouse_move(DangoApp *a,int x,int y,UINT flags){(void)flags;if(a->drag_splitter>=0){if(a->drag_splitter==0)a->panel_left_ratio=fmin(.12,fmax(.045,(double)(x-16)/(a->window_width-32)));if(a->drag_splitter==1)a->inspector_ratio=fmin(.4,fmax(.16,(double)(a->window_width-x-16)/(a->window_width-32)));if(a->drag_splitter==2)a->timeline_ratio=fmin(.65,fmax(.22,(double)(a->window_height-y-36)/(a->window_height-98)));ui_layout(a,a->window_width,a->window_height);InvalidateRect(a->hwnd,NULL,FALSE);return;}if(a->dragging_clip&&a->drag_clip>=0){Clip*c=&a->project.clips[a->drag_clip];double sec=(x-a->drag_origin.x)/a->project.pixels_per_second;c->start=fmax(0,a->drag_start+sec);int total=a->project.visible_video_tracks+a->project.visible_audio_tracks;int top=a->timeline.top+55;int rh=(a->timeline.bottom-top-38)/imax(total,1);int row=(y-top)/imax(rh,1);if(c->kind==LANE_VIDEO){if(row>=0&&row<3){c->track=row;if(row+1>a->project.visible_video_tracks)a->project.visible_video_tracks=row+1;}}else if(c->kind==LANE_AUDIO){int ar=row-a->project.visible_video_tracks;if(ar>=0&&ar<3){c->track=ar;if(ar+1>a->project.visible_audio_tracks)a->project.visible_audio_tracks=ar+1;}}InvalidateRect(a->hwnd,NULL,FALSE);}}
void ui_mouse_up(DangoApp *a,int x,int y){(void)x;(void)y;a->drag_splitter=-1;if(a->dragging_clip&&a->drag_clip>=0){Clip*c=&a->project.clips[a->drag_clip];LaneKind kind=c->kind;int track=c->track;if(kind!=LANE_EFFECT)project_compact_lane(&a->project,kind,track);a->dragging_clip=false;a->drag_clip=-1;ReleaseCapture();}InvalidateRect(a->hwnd,NULL,FALSE);}
void ui_key(DangoApp *a,WPARAM k){if(k=='V')a->project.tool=TOOL_SELECT;else if(k=='C')a->project.tool=TOOL_BLADE;else if(k=='H')a->project.tool=TOOL_HAND;else if(k=='T')a->project.tool=TOOL_TEXT;else if(k==VK_DELETE)project_remove_clip(&a->project,a->project.selected_id);else if(k==VK_SPACE)a->project.playing=!a->project.playing;else if(k==VK_F5)media_import_dialog(a);InvalidateRect(a->hwnd,NULL,FALSE);}
